from pathlib import Path
import copy,importlib.util,json,tempfile,unittest,shutil
ROOT=Path(__file__).resolve().parents[1]/'skills/qa-and-release-assets'
spec=importlib.util.spec_from_file_location('review_validator',ROOT/'scripts/validate_outline_review.py');v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v)
BASE=json.loads((ROOT/'examples/outline-review/worked-review.json').read_text())
class Tests(unittest.TestCase):
 def setUp(self):self.d=copy.deepcopy(BASE)
 def errors(self):return v.validate_review(self.d,ROOT)
 def reject(self,phrase):self.assertTrue(any(phrase in e for e in self.errors()),self.errors())
 def test_valid_example(self):self.assertEqual(self.errors(),[])
 def test_full_review_does_not_force_revision(self):
  self.d['mode']='full-review';self.d['artifacts']=self.d['artifacts'][:1];self.d['dispositions']=self.d['dispositions'][:1];self.d['revised_objective_ids']=[];self.d['objective_treatments']=[];self.d.pop('proposed_timing');self.d['handoff']['artifact_ids']=['OUT-01'];self.d['qa_bridge']['candidate_results']=self.d['qa_bridge']['candidate_results'][:1]
  for f in self.d['findings']:f['target_artifact_id']=None
  self.assertEqual(self.errors(),[])
 def test_original_total(self):self.d['original_timing']['row_total']=90;self.reject('arithmetic mismatch')
 def test_variance(self):self.d['original_timing']['variance']=0;self.reject('variance mismatch')
 def test_pause_is_not_instruction(self):self.d['proposed_timing']['instructional_minutes']=90;self.reject('instructional_minutes mismatch')
 def test_unknown_original_allocation(self):self.d['original_timing']['instructional_minutes']=90;self.reject('unknown allocation')
 def test_source_agenda_drift(self):self.d['original_timing']['agenda'][0]['minutes']=11;self.reject('source agenda differs')
 def test_start_gap(self):self.d['proposed_timing']['agenda'][1]['start_minute']=9;self.reject('start minute')
 def test_count_summary(self):self.d['severity_counts']['Major']=4;self.reject('Severity counts')
 def test_invalid_severity(self):self.d['findings'][0]['severity']='High';self.reject('invalid severity')
 def test_severity_needs_rationale(self):self.d['findings'][0]['severity_rationale']='';self.reject('severity_rationale')
 def test_duplicate_findings(self):self.d['findings'][1]['id']='F-01';self.reject('unique')
 def test_unknown_source(self):self.d['findings'][0]['evidence']['source_ids']=['SRC-999'];self.reject('unknown reference')
 def test_unfounded_quote(self):self.d['findings'][1]['evidence']['text']='An invented source sentence';self.reject('original evidence quote missing')
 def test_dropped_tone_objective(self):self.d['objective_treatments'].pop();self.reject('exactly one treatment')
 def test_unmapped_revised_objective(self):self.d['revised_objective_ids'].append('R-99');self.reject('Unmapped revised')
 def test_missing_objective_owner(self):self.d['objective_treatments'][2]['decision_owner']='';self.reject('rationale/owner')
 def test_false_closure(self):self.d['findings'][0]['status']='Verified resolved';self.reject('closure verification required')
 def test_stale_closure(self):
  self.d['findings'][0].update(status='Verified resolved',verification=dict(artifact_id='OUT-02',artifact_version='1.0',method='Document review',reviewer='Reviewer',date='2026-10-21',evidence=dict(path='examples/outline-review/03-proposed-revision.md',quote='85 minutes',result='Arithmetic inspected')));self.reject('closure version stale')
 def test_incomplete_deferral(self):self.d['findings'][0]['status']='Deferred';self.reject('deferral decision')
 def test_proposal_cannot_upgrade_disposition(self):self.d['dispositions'][1]['value']='Minor revisions required';self.reject('unresolved Major/Critical')
 def test_missing_blocker(self):self.d['dispositions'][1]['blocking_finding_ids'].pop();self.reject('omits material')
 def test_unknown_disposition(self):self.d['dispositions'][0]['value']='Approved';self.reject('Invalid disposition')
 def test_missing_quality_check(self):self.d['quality_checks'].pop();self.reject('twelve')
 def test_empty_quality_evidence(self):self.d['quality_checks'][0]['evidence']={};self.reject('evidence quote')
 def test_stale_quality(self):self.d['quality_checks'][0]['review_version']='1.0';self.reject('stale review')
 def test_invalid_quality_date(self):self.d['quality_checks'][0]['date']='yesterday';self.reject('actual ISO date')
 def test_exclusion_cannot_pass(self):self.d['quality_checks'][0].update(applicable=False,status='Pass',rationale='Skipped');self.reject('excluded check')
 def test_wrong_handoff_destination(self):self.d['handoff']['destination']='course-creator';self.reject('Wrong handoff')
 def test_false_handoff_execution(self):self.d['handoff']['status']='Executed';self.reject('claim execution')
 def test_handoff_missing_finding(self):self.d['handoff']['tasks']=[t for t in self.d['handoff']['tasks'] if 'F-06' not in t['finding_ids']];self.reject('misses unresolved defect')
 def test_handoff_unknown_objective(self):self.d['handoff']['tasks'][0]['objective_ids']=['O-99'];self.reject('unknown reference')
 def test_unknown_dependency(self):self.d['handoff']['tasks'][0]['dependencies']=['UNKNOWN'];self.reject('unknown reference')
 def test_dependency_cycle(self):self.d['handoff']['tasks'][0]['dependencies']=['T-02'];self.reject('Cyclic handoff')
 def test_handoff_loses_material_decision(self):self.d['handoff']['scope_decision_ids'].pop();self.reject('misses material scope')
 def test_unsafe_evidence_path(self):self.d['quality_checks'][0]['evidence']['path']='../../../../../etc/passwd';self.reject('unsafe local path')
 def test_modified_artifact(self):
  with tempfile.TemporaryDirectory() as tmp:
   root=Path(tmp);shutil.copytree(ROOT/'examples',root/'examples');p=root/'examples/outline-review/01-flawed-outline.md';p.write_text(p.read_text()+'\nChanged\n');self.assertTrue(any('artifact hash mismatch' in e for e in v.validate_review(self.d,root)))
 def test_bridge_cannot_pass_material_defect(self):self.d['qa_bridge']['candidate_results'][0]['qa_status']='QA PASS';self.reject('cannot pass unresolved')
 def test_bridge_cannot_infer_authorization(self):self.d['qa_bridge']['candidate_results'][0]['authorization']='AUTHORIZED';self.reject('infer release authorization')
 def test_bridge_cannot_infer_execution(self):self.d['qa_bridge']['candidate_results'][0]['release_executed']=True;self.reject('infer release execution')
 def test_bridge_keeps_scope(self):self.d['qa_bridge']['scope']='full-release';self.reject('outline-design scope')
 def test_bridge_preserves_severity(self):self.d['qa_bridge']['defect_map'][0]['qa_severity']='MINOR';self.reject('severity mapping differs')
 def test_bridge_requires_candidate_coverage(self):self.d['qa_bridge']['candidate_results'].pop();self.reject('candidate coverage')
 def test_bridge_requires_unique_aliases(self):self.d['qa_bridge']['defect_map'][1]['qa_defect_id']='DEF-OUT-01';self.reject('aliases must be unique')
 def test_bridge_conditions_need_acceptance(self):self.d['dispositions'][1]['value']='Minor revisions required';self.d['qa_bridge']['candidate_results'][1]['qa_status']='QA PASS WITH CONDITIONS';self.reject('conditions require explicit')
 def test_bad_record(self):self.assertTrue(v.validate_review([],ROOT))
if __name__=='__main__':unittest.main(verbosity=2)
